import sys

def shortest_regular_bracket_sequence(s, t):
    n, m = len(s), len(t)
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    for i in range(n + 1):
        for j in range(m + 1):
            if i == 0:
                dp[i][j] = j
            elif j == 0:
                dp[i][j] = i
            elif s[i - 1] == '(' and t[j - 1] == ')':
                dp[i][j] = min(dp[i - 1][j - 1], dp[i][j])
            elif s[i - 1] == ')':
                dp[i][j] = min(2 + dp[i - 1][j], dp[i][j])
            elif t[j - 1] == ')':
                dp[i][j] += min(2 + dp[i][j - 1], dp[i][j])
            else:
                dp[i][j] = min(dp[i - 1][j] + 1, dp[i][j - 1] + 1, dp[i][j])

    result = []
    i, j = n, m
    balance = 0

    while i > 0 or j > 0:
        if i > 0 and j > 0 and s[i - 1] == '(' and t[j - 1] != ')' and dp[i][j] == dp[i - 1][j - 1] + 1:
            result.append('(')
            i -= 1
            j -= 1
            balance += 1
        elif i > 0 and (j == 0 or dp[i][j] == dp[i - 1][j] + 1):
            if s[i - 1] == '(':
                result.append('(')
                balance += 1
            else:
                result.append(')')
                balance -= 1
            i -= 1
        elif j > 0 and (i == 0 or dp[i][j] == dp[i][j - 1] + 1):
            if t[j - 1] == '(':
                result.append('(')
                balance +=1
            else:
                result.append(')')
                balance -= 1 
            j -= 1
        else:
            result.append('()')
            i -= 1
            j -= 1

    while balance > 0:
        result.append(')')
        balance -= 1

    return ''.join(result[::-1])

input = sys.stdin.read().strip().split('\n')
s, t = input[0], input[1]
print(shortest_regular_bracket_sequence(s, t))
